module multi_pipe_4bit #(
    parameter size = 4
) (
    input clk,
    input rst_n,
    input [size-1:0] mul_a,
    input [size-1:0] mul_b,
    output [2*size-1:0] mul_out
);

    reg [2*size-1:0] partial_products [size-1:0];
    reg [2*size-1:0] registers [size/2-1:0];
    reg [2*size-1:0] product;

    // Multiplication operation
    genvar i;
    generate
        for (i = 0; i < size; i = i + 1) begin
            always @(*) begin
                partial_products[i] = (mul_b[i]) ? (mul_a << i) : 'd0;
            end
        end
    endgenerate

    // Add of partial products
    integer j;
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            for (j = 0; j < size/2; j = j + 1) begin
                registers[j] <= 'd0;
            end
        end else begin
            for (j = 0; j < size/2; j = j + 1) begin
                registers[j] <= partial_products[2*j] + partial_products[2*j+1];
            end
        end
    end

    // Final product calculation
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            product <= 'd0;
        end else begin
            product <= registers[0];
            for (j = 1; j < size/2; j = j + 1) begin
                product <= {product[2*size-1:2*j*size], registers[j]};
            end
        end
    end

    assign mul_out = product;

endmodule
